from __future__ import annotations
import json,os,sqlite3,time,urllib.parse,urllib.request
from pathlib import Path
SCHEMA='eira2_library_federation_wing_v1'
ROOT=Path(os.environ.get('EIRA_LIVE_ROOT','/media/domenicleonetti/easystore/EIRA/LIVE')).resolve()
DB=ROOT/'eira_probe'/'universe_library'/'source_vault'/'source_index.sqlite3'
CACHE=ROOT/'eira_probe'/'universe_library'/'federation_cache'
UA='EIRA2-Library-Federation/1.0 (remote-first; metadata-only cache)'
SOURCES={
'local':{'name':'EIRA Local Library','mode':'local','enabled':True},
'loc':{'name':'Library of Congress','mode':'remote','endpoint':'https://www.loc.gov/books/','enabled':True},
'nasa':{'name':'NASA NTRS','mode':'remote','endpoint':'https://ntrs.nasa.gov/api/citations/search','enabled':True},
'osti':{'name':'DOE OSTI','mode':'remote','endpoint':'https://www.osti.gov/api/v1/records','enabled':True},
'usgs':{'name':'USGS Publications Warehouse','mode':'remote','endpoint':'https://pubs.usgs.gov/pubs-services/publication','enabled':True},
'ncbi':{'name':'NCBI Bookshelf','mode':'remote','endpoint':'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/','enabled':True},
'openlibrary':{'name':'Open Library','mode':'remote','endpoint':'https://openlibrary.org/search.json','enabled':True},
'govinfo':{'name':'GovInfo','mode':'remote_keyed','endpoint':'https://api.govinfo.gov/','env':'GOVINFO_API_KEY','enabled':bool(os.environ.get('GOVINFO_API_KEY'))},
'smithsonian':{'name':'Smithsonian Open Access','mode':'remote_keyed','endpoint':'https://api.si.edu/openaccess/api/v1.0/search','env':'SMITHSONIAN_API_KEY','enabled':bool(os.environ.get('SMITHSONIAN_API_KEY'))}}
def _get(url,p=None):
 if p:url+=('&' if '?' in url else '?')+urllib.parse.urlencode(p,doseq=True)
 q=urllib.request.Request(url,headers={'User-Agent':UA,'Accept':'application/json'})
 with urllib.request.urlopen(q,timeout=20) as r:return json.loads(r.read().decode('utf-8','replace'))
def _s(v):
 if v is None:return ''
 if isinstance(v,(list,tuple)):return '; '.join(_s(x) for x in v if _s(x))
 if isinstance(v,dict):return json.dumps(v,ensure_ascii=False,sort_keys=True)
 return str(v)
def _r(src,i,t,a='',s='',u='',rights='',d='',raw=None,remote=True):
 return {'source_name':src,'source_work_id':_s(i),'title':_s(t),'authors':_s(a),'subjects':_s(s),'source_url':_s(u),'rights':_s(rights),'source_release_date':_s(d),'source_is_not_fact':True,'remote_only':remote,'metadata':raw if isinstance(raw,dict) else {}}
class FederationWing:
 def __init__(self,db_path=DB):self.db_path=Path(db_path);CACHE.mkdir(parents=True,exist_ok=True)
 def status(self):return {'schema':SCHEMA,'policy':'remote-first, metadata-first, no automatic full-text mirroring','sources':SOURCES}
 def local(self,q,n):
  if not self.db_path.is_file():return []
  c=sqlite3.connect(str(self.db_path),timeout=20);c.row_factory=sqlite3.Row
  try:
   z=f'%{q}%';rows=c.execute("SELECT source_name,source_work_id,title,authors,subjects,source_url,rights,source_release_date,metadata_json FROM works WHERE title LIKE ? OR authors LIKE ? OR subjects LIKE ? LIMIT ?",(z,z,z,n)).fetchall();out=[]
   for x in rows:
    try:m=json.loads(x['metadata_json'] or '{}')
    except Exception:m={}
    out.append(_r(x['source_name'],x['source_work_id'],x['title'],x['authors'],x['subjects'],x['source_url'],x['rights'],x['source_release_date'],m,False))
   return out
  finally:c.close()
 def loc(self,q,n):
  d=_get('https://www.loc.gov/books/',{'fo':'json','q':q,'c':n});return [_r('library_of_congress',x.get('id') or x.get('url'),x.get('title'),x.get('contributor') or x.get('creator'),x.get('subject'),x.get('id') or x.get('url'),x.get('rights') or x.get('access_restricted'),x.get('date'),x) for x in d.get('results',[])[:n]]
 def openlibrary(self,q,n):
  d=_get('https://openlibrary.org/search.json',{'q':q,'limit':n});return [_r('open_library',x.get('key'),x.get('title'),x.get('author_name'),(x.get('subject') or [])[:12],'https://openlibrary.org'+x.get('key',''),'discovery_metadata_only',x.get('first_publish_year'),x) for x in d.get('docs',[])[:n]]
 def osti(self,q,n):
  d=_get('https://www.osti.gov/api/v1/records',{'q':q,'rows':n});rows=d if isinstance(d,list) else d.get('records',[]);return [_r('doe_osti',x.get('osti_id'),x.get('title'),x.get('authors'),x.get('subjects'),x.get('product_url') or x.get('doi'),x.get('license') or x.get('access_limitation'),x.get('publication_date'),x) for x in rows[:n]]
 def nasa(self,q,n):
  d=_get('https://ntrs.nasa.gov/api/citations/search',{'q':q,'size':n});rows=(d.get('results') or d.get('items') or d.get('records') or []) if isinstance(d,dict) else [];return [_r('nasa_ntrs',x.get('id'),x.get('title'),x.get('authorAffiliations') or x.get('authors'),x.get('keywords'),'https://ntrs.nasa.gov/citations/'+str(x.get('id','')),x.get('copyright') or x.get('distribution'),x.get('publicationDate') or x.get('createdAt'),x) for x in rows[:n]]
 def usgs(self,q,n):
  d=_get('https://pubs.usgs.gov/pubs-services/publication',{'q':q,'page_size':n});rows=(d.get('records') or d.get('publications') or d.get('data') or []) if isinstance(d,dict) else (d if isinstance(d,list) else []);return [_r('usgs_publications',x.get('id') or x.get('indexId') or x.get('publicationId'),x.get('title'),x.get('authors') or x.get('author'),x.get('topics') or x.get('keywords'),x.get('publicationUrl') or x.get('url'),'item-level access terms apply',x.get('publicationYear') or x.get('publicationDate'),x) for x in rows[:n]]
 def ncbi(self,q,n):
  b='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/';p={'db':'books','term':q,'retmode':'json','retmax':n,'tool':'EIRA2_Universe_Library'};ids=((_get(b+'esearch.fcgi',p).get('esearchresult') or {}).get('idlist') or [])
  if not ids:return []
  d=_get(b+'esummary.fcgi',{'db':'books','id':','.join(ids),'retmode':'json','version':'2.0','tool':'EIRA2_Universe_Library'}).get('result') or {};return [_r('ncbi_bookshelf',i,(d.get(str(i)) or {}).get('title'),(d.get(str(i)) or {}).get('authors'),'biomedical_bookshelf','https://www.ncbi.nlm.nih.gov/books/'+str(i),'title_specific_permissions_required',(d.get(str(i)) or {}).get('pubdate'),d.get(str(i)) or {}) for i in ids[:n]]
 def search_source(self,s,q,limit=5):
  n=max(1,min(int(limit),20));f={'local':self.local,'loc':self.loc,'nasa':self.nasa,'osti':self.osti,'usgs':self.usgs,'ncbi':self.ncbi,'openlibrary':self.openlibrary}.get(s)
  if not f:raise ValueError('source_not_directly_searchable:'+s)
  return f(q,n)
 def search(self,q,sources=None,limit_per_source=5):
  ss=sources or ['local','loc','nasa','osti','usgs','ncbi','openlibrary'];results=[];failures={}
  for s in ss:
   try:results+=self.search_source(s,q,limit_per_source)
   except Exception as e:failures[s]=f'{type(e).__name__}:{e}'[:500]
  rec={'schema':SCHEMA,'query':q,'sources_requested':ss,'result_count':len(results),'failures':failures,'source_is_not_fact':True,'metadata_first':True,'full_text_auto_download':False,'unix':time.time(),'results':results};(CACHE/f'query_{int(time.time()*1000)}.json').write_text(json.dumps(rec,ensure_ascii=False,sort_keys=True,indent=2));return rec
def describe():return FederationWing().status()
if __name__=='__main__':print(json.dumps(describe(),indent=2,sort_keys=True))
